@page "/chat"
@layout sv_fc55b6e89f1c4a1085798aafcc7cfb50.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_fc55b6e89f1c4a1085798aafcc7cfb50.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="chat-app">
    @* ───── Left Sidebar: Channel List ───── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h2>Channels</h2>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var ch in _channels)
                {
                    <li class="channel-item @(ch.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(ch)">
                        <div class="channel-name"># @ch.Name</div>
                        <div class="channel-desc">@Truncate(ch.Description, 40)</div>
                        @if (ch.UnreadCount > 0)
                        {
                            <span class="unread-badge">@ch.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ───── Main Message Area ───── *@
    <section class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <header class="message-header">
                <h3># @_activeChannel.Name</h3>
                <span class="header-desc">@_activeChannel.Description</span>
            </header>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScrollAsync">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @key="msg.Id">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <strong class="author">@msg.Author</strong>
                                    <time class="timestamp" title="@msg.SentAt.ToString("g")">@RelativeTime(msg.SentAt)</time>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reactions-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                                    @onclick="() => ReactAsync(msg.Id, r.Emoji)">
                                                @r.Emoji @r.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @{ var replyCount = GetReplyCount(msg.Id); }
                                @if (replyCount > 0)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
                                        @replyCount @(replyCount == 1 ? "reply" : "replies")
                                    </button>
                                }

                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread" @onclick="() => OpenThreadAsync(msg)">💬 Reply</button>
                                    <button class="action-btn emoji-trigger" @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option" @onclick="() => PickEmojiAsync(msg.Id, emoji)">@emoji</button>
                                        }
                                    </div>
                                }
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea class="compose-input" rows="2" placeholder="Message #@_activeChannel.Name"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="OnComposeKeyDown"></textarea>
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_newMessageText)"
                        @onclick="SendMessageAsync">Send</button>
            </div>
        }
        else
        {
            <div class="empty-state">Select a channel to start chatting</div>
        }
    </section>

    @* ───── Right Panel: Thread View ───── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <header class="thread-header">
                <h4>Thread</h4>
                <button class="close-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </header>

            <div class="thread-root-quote">
                <strong>@_threadRootMessage.Author</strong>
                <p>@_threadRootMessage.Content</p>
            </div>

            <div class="thread-messages">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-row" @key="reply.Id">
                            <div class="message-bubble compact">
                                <div class="message-meta">
                                    <strong class="author">@reply.Author</strong>
                                    <time class="timestamp">@RelativeTime(reply.SentAt)</time>
                                </div>
                                <div class="message-content">@reply.Content</div>

                                @if (reply.Reactions.Count > 0)
                                {
                                    <div class="reactions-row">
                                        @foreach (var r in reply.Reactions)
                                        {
                                            <button class="reaction-badge" title="@string.Join(", ", r.Users)"
                                                    @onclick="() => ReactAsync(reply.Id, r.Emoji)">
                                                @r.Emoji @r.Users.Count
                                            </button>
                                        }
                                    </div>
                                }
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="compose-area">
                <textarea class="compose-input" rows="2" placeholder="Reply…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadReplyKeyDown"></textarea>
                <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(_threadReplyText)"
                        @onclick="SendThreadReplyAsync">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    // ── Data ──
    private List<Channel>? _channels;
    private List<Message>? _messages;
    private List<Message>? _threadMessages;

    // ── State ──
    private int _activeChannelId;
    private Channel? _activeChannel;
    private Message? _threadRootMessage;
    private bool _threadOpen;

    private string _newMessageText = string.Empty;
    private string _threadReplyText = string.Empty;
    private int? _emojiPickerMessageId;

    // Pagination
    private const int PageSize = 30;
    private int _skip;
    private bool _loadingMore;
    private bool _allLoaded;

    // Thread reply counts keyed by root message id
    private readonly Dictionary<int, int> _replyCounts = new();

    private ElementReference _messageListRef;
    private IJSObjectReference? _jsModule;

    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0]);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-fc55b6e89f1c4a1085798aafcc7cfb50/Components/Pages/Chat.razor.js");
        }
    }

    // ── Channel selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _skip = 0;
        _allLoaded = false;
        _emojiPickerMessageId = null;
        _replyCounts.Clear();

        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _skip = _messages.Count;

        BuildReplyCounts(_messages);

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread badge
        _channels = await ChatService.GetChannelsAsync();

        await ScrollToBottomAsync();
    }

    // ── Pagination (scroll-to-top) ──

    private async Task OnMessageListScrollAsync()
    {
        if (_loadingMore || _allLoaded || _messages is null) return;

        var scrollTop = await GetScrollTopAsync();
        if (scrollTop > 50) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _skip, PageSize);
        if (older.Count == 0)
        {
            _allLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            _skip += older.Count;
            BuildReplyCounts(older);
        }

        _loadingMore = false;
    }

    // ── Sending messages ──

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannel is null) return;

        var text = _newMessageText.Trim();
        _newMessageText = string.Empty;

        var msg = await ChatService.SendMessageAsync(_activeChannelId, text, null);
        _messages?.Add(msg);
        _skip++;

        await ScrollToBottomAsync();
    }

    private async Task OnComposeKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplyText = string.Empty;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null) return;

        var text = _threadReplyText.Trim();
        _threadReplyText = string.Empty;

        var reply = await ChatService.SendMessageAsync(
            _threadRootMessage.ChannelId, text, _threadRootMessage.Id);

        _threadMessages?.Add(reply);

        // Update reply count in main view
        _replyCounts[_threadRootMessage.Id] =
            _replyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
    }

    private async Task OnThreadReplyKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task PickEmojiAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ReactAsync(messageId, emoji);
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh the message list to show updated reaction
        if (_messages is not null)
        {
            var idx = _messages.FindIndex(m => m.Id == messageId);
            if (idx >= 0)
            {
                var updated = await ChatService.GetMessagesAsync(_activeChannelId, idx, 1);
                if (updated.Count > 0)
                    _messages[idx] = updated[0];
            }
        }

        // Also refresh thread messages if thread is open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    // ── Helpers ──

    private void BuildReplyCounts(List<Message> messages)
    {
        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            _replyCounts[rootId] = _replyCounts.GetValueOrDefault(rootId) + 1;
        }
    }

    private int GetReplyCount(int messageId) =>
        _replyCounts.GetValueOrDefault(messageId);

    private static string Truncate(string text, int maxLen) =>
        text.Length <= maxLen ? text : string.Concat(text.AsSpan(0, maxLen), "…");

    private static string RelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private async Task ScrollToBottomAsync()
    {
        if (_jsModule is not null)
        {
            try { await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef); }
            catch (JSDisconnectedException) { }
        }
    }

    private async Task<double> GetScrollTopAsync()
    {
        if (_jsModule is not null)
        {
            try { return await _jsModule.InvokeAsync<double>("getScrollTop", _messageListRef); }
            catch (JSDisconnectedException) { return 100; }
        }
        return 100;
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try { await _jsModule.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }
    }
}

