/* ═══════════════════════════════════════════════
   Chat Page – Scoped Styles
   ═══════════════════════════════════════════════ */

/* ── Root layout ── */
.chat-app {
    display: flex;
    height: 100vh;
    width: 100%;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, sans-serif;
    color: #1d1c1d;
    background: #fff;
    overflow: hidden;
}

/* ── Left Sidebar ── */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid rgba(255,255,255,.1);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    font-weight: 700;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 6px 16px;
    cursor: pointer;
    position: relative;
    transition: background .15s;
    border-radius: 6px;
    margin: 0 8px;
}

.channel-item:hover {
    background: rgba(255,255,255,.08);
}

.channel-item.active {
    background: #1264a3;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: .95rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    font-size: .75rem;
    opacity: .7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 1px;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #e01e5a;
    color: #fff;
    font-size: .7rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* ── Main Message Area ── */
.message-area {
    flex: 0 0 55%;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #e8e8e8;
    overflow: hidden;
    transition: flex .2s ease;
}

.message-area.expanded {
    flex: 1 1 80%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.message-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
}

.header-desc {
    font-size: .85rem;
    color: #616061;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

/* ── Message list ── */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #999;
    font-size: .85rem;
}

/* ── Single message ── */
.message-row {
    position: relative;
}

.message-bubble {
    padding: 6px 12px;
    border-radius: 6px;
    position: relative;
    transition: background .1s;
}

.message-bubble:hover {
    background: #f8f8f8;
}

.message-bubble.compact {
    padding: 4px 10px;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-size: .9rem;
    font-weight: 700;
    color: #1d1c1d;
}

.timestamp {
    font-size: .75rem;
    color: #999;
}

.message-content {
    font-size: .925rem;
    line-height: 1.46;
    word-break: break-word;
    white-space: pre-wrap;
}

/* ── Reactions ── */
.reactions-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    background: #f0f0f0;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: .8rem;
    cursor: pointer;
    transition: background .15s;
}

.reaction-badge:hover {
    background: #ddf4ff;
    border-color: #1264a3;
}

/* ── Thread link ── */
.thread-link {
    display: inline-block;
    margin-top: 4px;
    font-size: .8rem;
    color: #1264a3;
    font-weight: 600;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Hover action buttons ── */
.message-actions {
    display: none;
    position: absolute;
    top: -6px;
    right: 4px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0,0,0,.1);
    padding: 2px;
    gap: 2px;
    z-index: 5;
}

.message-bubble:hover .message-actions {
    display: flex;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 8px;
    font-size: .8rem;
    border-radius: 4px;
    color: #555;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
    color: #111;
}

/* ── Emoji picker ── */
.emoji-picker {
    position: absolute;
    top: -4px;
    right: 120px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 4px;
    box-shadow: 0 4px 12px rgba(0,0,0,.15);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background .12s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ── Compose area ── */
.compose-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.compose-input {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: .9rem;
    font-family: inherit;
    outline: none;
    transition: border-color .15s;
}

.compose-input:focus {
    border-color: #1264a3;
    box-shadow: 0 0 0 1px #1264a3;
}

.send-btn {
    padding: 8px 20px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    font-size: .9rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background .15s;
}

.send-btn:hover:not(:disabled) {
    background: #006049;
}

.send-btn:disabled {
    opacity: .5;
    cursor: default;
}

/* ── Right Thread Panel ── */
.thread-panel {
    width: 25%;
    min-width: 280px;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #e8e8e8;
    background: #fff;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #111;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    background: #fafafa;
    flex-shrink: 0;
}

.thread-root-quote strong {
    font-size: .85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: .88rem;
    color: #333;
    line-height: 1.4;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

